  "summary": "The code suffered from critical security vulnerabilities due to insecure random number generation and plaintext token storage. I have refactored the implementation to use the 'secrets' module, implemented token hashing, and added type hints and documentation for better maintainability.",
  "fixed_code": "import secrets\nimport string\nimport time\nimport hashlib\nfrom typing import Dict, Any\n\nTOKEN_EXPIRY_SECONDS = 900\n\ndef make_reset_token(length: int = 32) -> str:\n    \"\"\"Generates a cryptographically secure random URL-safe token.\"\"\"\n    return secrets.token_urlsafe(length)\n\ndef issue_reset(store: Dict[str, Any], email: str) -> str:\n    \"\"\"Issues a hashed reset token and stores it with an expiration timestamp.\"\"\"\n    token = make_reset_token()\n    hashed_token = hashlib.sha256(token.encode()).hexdigest()\n    store[hashed_token] = {\n        \"email\": email, \n        \"expires\": time.time() + TOKEN_EXPIRY_SECONDS\n    }\n    return token"
